validator:
function validate([operations, args]) {
  const nums = args[0][0];
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'The wrapped iterator holds 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is between 1 and 1000.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls are made.';
  let used = 0;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (op !== 'next' && op !== 'peek' && op !== 'hasNext') return `Unknown operation ${op}.`;
    if (op !== 'hasNext' && used >= nums.length) return `Call ${i} (${op}) is made after every value was returned.`;
    if (op === 'next') used++;
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [operations, args] = input;
  const values = args[0][0];
  let position = 0;
  // The wrapped iterator: only hasNext() and next(), like LeetCode's Iterator.
  const iterator = {
    hasNext() { return position < values.length; },
    next() {
      if (position >= values.length) throw new Error('next() was called on the wrapped iterator after its last value.');
      return values[position++];
    },
  };
  const peeking = new solve(iterator);
  const results = [null];
  for (let i = 1; i < operations.length; i++) {
    const name = operations[i];
    if (typeof peeking[name] !== 'function') throw new Error(`PeekingIterator needs a ${name}() method.`);
    const value = peeking[name]();
    results.push(value === undefined ? null : value);
  }
  return results;
}

