class PeekingIterator {
  constructor(iterator) {
    this.iterator = iterator;
    this.hasPeeked = false;
    this.peeked = null;
  }

  peek() {
    if (!this.hasPeeked) {
      this.peeked = this.iterator.next();
      this.hasPeeked = true;
    }
    return this.peeked;
  }

  next() {
    if (this.hasPeeked) {
      this.hasPeeked = false;
      return this.peeked;
    }
    return this.iterator.next();
  }

  hasNext() {
    return this.hasPeeked || this.iterator.hasNext();
  }
}

