class PeekingIterator {
  // Drain the whole wrapped iterator up front, then answer from an array.
  constructor(iterator) {
    this.items = [];
    while (iterator.hasNext()) this.items.push(iterator.next());
    this.index = 0;
  }
  peek() { return this.items[this.index]; }
  next() { return this.items[this.index++]; }
  hasNext() { return this.index < this.items.length; }
}

