function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 1 + Math.floor(rand() * 6);
  const top = large || rand() < 0.5 ? 1000 : 4;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const calls = large ? 499 : 1 + Math.floor(rand() * 12);
  const operations = ['PeekingIterator'];
  const args = [[nums]];
  let used = 0;
  while (operations.length - 1 < calls) {
    const roll = rand();
    let op = roll < 0.4 ? 'next' : roll < 0.75 ? 'peek' : 'hasNext';
    if (used === n) op = 'hasNext';
    if (op === 'next') used++;
    operations.push(op);
    args.push([]);
    if (used === n && rand() < 0.5) {
      if (operations.length < 500) { operations.push('hasNext'); args.push([]); }
      break;
    }
  }
  return [operations, args];
}
